begin;
insert into auth.users(id,email) values('15000000-0000-0000-0000-000000000001','resource-owner@example.test'),('15000000-0000-0000-0000-000000000002','resource-other@example.test');
insert into public.courses(id,title,slug,status,is_free,price_paise) values('15100000-0000-0000-0000-000000000001','Private resource fixture','private-resource-fixture','published',false,100);
insert into public.course_modules(id,course_id,title,status) values('15200000-0000-0000-0000-000000000001','15100000-0000-0000-0000-000000000001','Module','published');
insert into public.lessons(id,module_id,title,slug,status) values('15300000-0000-0000-0000-000000000001','15200000-0000-0000-0000-000000000001','Lesson','resource','published');
insert into public.lesson_contents(lesson_id,body,private_resource_path) values('15300000-0000-0000-0000-000000000001','Protected','lessons/15300000-0000-0000-0000-000000000001/15400000-0000-0000-0000-000000000001.pdf');
select t.throws($q$update public.lesson_contents set private_resource_path='lessons/15300000-0000-0000-0000-000000000099/15400000-0000-0000-0000-000000000001.pdf' where lesson_id='15300000-0000-0000-0000-000000000001'$q$,'23514','resource path must belong to its lesson');
set local role anon;
select t.eq(public.can_read_lesson('15300000-0000-0000-0000-000000000001'),false,'anonymous resource access denied');
select t.eq((select count(*) from public.lesson_contents where lesson_id='15300000-0000-0000-0000-000000000001'),0::bigint,'resource path hidden from guest');
reset role;
insert into public.content_entitlements(user_id,course_id) values('15000000-0000-0000-0000-000000000001','15100000-0000-0000-0000-000000000001');
select set_config('request.jwt.claims','{"sub":"15000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select t.eq(public.can_read_lesson('15300000-0000-0000-0000-000000000001'),true,'entitled student may request resource');
select t.eq((select count(*) from public.lesson_contents where lesson_id='15300000-0000-0000-0000-000000000001' and private_resource_path is not null),1::bigint,'entitled body includes private resource reference');
reset role;
select set_config('request.jwt.claims','{"sub":"15000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select t.eq((select count(*) from public.lesson_contents where lesson_id='15300000-0000-0000-0000-000000000001'),0::bigint,'another student cannot retrieve resource reference');
reset role;
rollback;
